    "taxonId": 321045,
    "summary": "An Australian-endemic genus of flowering shrubs, found in every state except the Northern Territory. Its species have simple alternating leaves, usually five-petalled flowers with inward-curving stamens, and capsules that release their seeds explosively.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2", "s1:p6"],
      "humanEdibility": []
    }
